(() => {
  'use strict';
  const data = window.PORTFOLIO, main = document.querySelector('main');
  const esc = value => String(value).replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
  const slot = value => value ? esc(value) : '&nbsp;';
  const tags = values => `<div class="tags">${values.map(x => `<span class="tag">${slot(x)}</span>`).join('')}</div>`;
  const eyebrow = text => `<div class="eyebrow"><span class="dot"></span>${slot(text)}</div>`;
  const safeUrl = value => {try {const u = new URL(value);return u.protocol === 'https:' ? u.href : '';} catch {return '';}};
  function figure() {return '<div class="mini-figure" aria-hidden="true"></div>';}
  function projectRow(p) {return `<a class="project-row" href="#research/${esc(p.id)}" aria-label="${esc(p.koreanTitle || '연구 프로젝트')}"><span class="project-number">${slot(p.number)}</span><div><div class="project-kicker">${slot(p.type)}</div><h3>${slot(p.koreanTitle)}</h3><p class="project-sub">${slot(p.type.toLowerCase())}</p>${tags(p.tags)}</div><span class="project-open" aria-hidden="true">→</span></a>`;}
  function noteCard(n) {return `<a class="note-card" href="#notes/${esc(n.slug)}" aria-label="${esc(n.title || '학습 노트')}"><div class="note-meta"><span class="note-category">${slot(n.category.toUpperCase())}</span><span>${slot([n.status,n.read].filter(Boolean).join(' · '))}</span></div><h3>${slot(n.title)}</h3><p>${slot(n.summary)}</p><div class="note-bottom">${tags(n.tags)}<span class="arrow" aria-hidden="true">↗</span></div></a>`;}
  function overview() {return `<div class="wrap"><section class="hero"><div>${eyebrow('Personal website')}<h1>${slot(data.profile.name)}</h1><p class="hero-subtitle">${slot(data.profile.subtitle)}</p><p class="hero-intro">${slot(data.profile.intro)}</p><div class="hero-links"><a class="button" href="#research">Explore research <span>↗</span></a><a class="text-link" href="#cv">View my CV ↗</a></div></div></section><div class="interest-strip"><span class="eyebrow">RESEARCH INTERESTS</span><div class="interest-items">${data.profile.interests.map(x=>`<span>${slot(x)}</span>`).join('')}</div></div><section class="section"><div class="section-heading"><div>${eyebrow('01 / Selected work')}<h2>Research & projects</h2></div><p>&nbsp;<br>&nbsp;</p></div>${data.projects.map(projectRow).join('')}<a class="text-link" href="#research">프로젝트 자세히 보기 ↗</a></section></div><section class="section section-shade"><div class="wrap"><div class="section-heading"><div>${eyebrow('02 / Learning in public')}<h2>Study notes</h2></div><a class="text-link" href="#notes">All study notes ↗</a></div><div class="note-grid">${data.notes.slice(0,4).map(noteCard).join('')}</div></div></section><div class="wrap"><section class="section about-section"><div>${eyebrow('03 / About me')}<h2>${slot(data.profile.name)}</h2><p>${slot(data.profile.about)}</p><div class="hero-links"><a class="text-link" href="#cv">Education & experience ↗</a></div></div><div><div class="about-detail"><span>EDUCATION</span><span>${slot(data.profile.education)}</span></div><div class="about-detail"><span>RESEARCH</span><span>${slot(data.profile.research)}</span></div><div class="about-detail"><span>TOOLKIT</span><span>${slot(data.profile.toolkit)}</span></div><div class="about-detail"><span>INTERESTS</span><span>${slot(data.profile.researchInterests)}</span></div></div></section></div>`;}
  function research(id) {
    const chosen = id ? data.projects.filter(p=>p.id===id) : data.projects;
    if(id && !chosen.length) return notFound();
    return `<div class="wrap"><div class="page-intro">${eyebrow('Research / Projects')}<h1>Research & projects</h1><p>&nbsp;</p></div>${id?'<a class="back" href="#research">← 모든 프로젝트</a>':''}${chosen.map(p=>`<section class="project-detail"><div><div class="project-kicker">${slot([p.number,p.type].filter(Boolean).join(' / '))}</div><h2>${slot(p.koreanTitle)}</h2><p>${slot(p.description)}</p><ul>${p.focus.map(x=>`<li>${slot(x)}</li>`).join('')}</ul>${tags(p.tags)}</div><div>${figure(p.figure)}<p class="figure-caption">${slot(p.note)}<br>&nbsp;</p></div></section>`).join('')}<div class="article-foot"><span>&nbsp;</span><a href="#notes">관련 공부 기록 ↗</a></div></div>`;
  }
  let selectedFilter='All', query='';
  function archive() {return `<div class="wrap archive"><div class="page-intro">${eyebrow('Study archive')}<h1>Study notes</h1><p>&nbsp;</p></div><label class="searchbar"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/></svg><input id="note-search" type="search" value="${esc(query)}" placeholder="제목, 키워드, 태그로 검색…" aria-label="학습 기록 검색"></label><div class="filters" aria-label="학습 기록 분류">${['All',...new Set(data.notes.map(n=>n.category).filter(Boolean))].map(c=>`<button class="filter ${c===selectedFilter?'active':''}" type="button" data-filter="${esc(c)}" aria-pressed="${c===selectedFilter}">${esc(c==='All'?'All notes':c)}</button>`).join('')}</div><p id="results-count" class="results-count" role="status" aria-live="polite"></p><div id="note-results" class="note-grid"></div></div>`;}
  function filterNotes() {
    const result=data.notes.filter(n=>(selectedFilter==='All'||n.category===selectedFilter)&&[n.title,n.summary,n.category,...n.tags,...n.sections.map(s=>s.text||'')].join(' ').toLocaleLowerCase().includes(query.trim().toLocaleLowerCase()));
    document.getElementById('results-count').textContent=data.notes.some(n=>n.title) ? `${result.length} / ${data.notes.length} NOTES` : '';
    document.getElementById('note-results').innerHTML=result.length?result.map(noteCard).join(''):'<p class="empty">일치하는 기록이 없습니다. 다른 검색어 또는 분류를 선택해 주세요.</p>';
    document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.filter===selectedFilter);b.setAttribute('aria-pressed',String(b.dataset.filter===selectedFilter));});
  }
  function article(slug) {
    const n=data.notes.find(x=>x.slug===slug);if(!n)return notFound();
    document.title=n.title ? `${n.title} — Personal website` : 'Study notes — Personal website';
    return `<div class="wrap"><article class="article"><a class="back" href="#notes">← Study archive</a>${eyebrow([n.category,n.status,n.read].filter(Boolean).join(' / '))}<h1>${slot(n.title)}</h1><p class="lead">${slot(n.summary)}</p><div class="article-tags">${tags(n.tags)}</div><div class="article-content">${n.sections.map(s=>`<section><h2>${slot(s.heading)}</h2>${s.text!==undefined?`<p>${slot(s.text)}</p>`:''}${s.formula!==undefined?`<div class="formula" role="math" aria-label="${esc(s.formula)}">${slot(s.formula)}</div>`:''}${s.list?`<ul>${s.list.map(x=>`<li>${slot(x)}</li>`).join('')}</ul>`:''}</section>`).join('')}</div><div class="article-foot"><span>&nbsp;</span><a href="#notes">다른 노트 읽기 ↗</a></div></article></div>`;
  }
  function cv() {return `<div class="wrap"><div class="page-intro">${eyebrow('Curriculum vitae')}<h1>${slot(data.profile.name)}</h1><p>${slot(data.profile.subtitle)}</p></div><div class="cv-layout"><aside class="cv-sidebar"><a class="button" href="./cv.html">Printable CV <span>↗</span></a><p>인쇄용 페이지에서 브라우저의 인쇄 기능으로 PDF를 저장할 수 있습니다.</p><p style="margin-top:15px">&nbsp;</p>${contact()}</aside><div><section class="cv-group"><h2>Education</h2><div class="cv-item"><h3>&nbsp;</h3><p>&nbsp;</p></div><div class="cv-item"><h3>&nbsp;</h3><p>&nbsp;<br>&nbsp;</p></div></section><section class="cv-group"><h2>Research experience</h2><div class="cv-item"><h3>&nbsp;</h3><p>&nbsp;</p><ul><li>&nbsp;</li><li>&nbsp;</li><li>&nbsp;</li></ul></div></section><section class="cv-group"><h2>Selected projects</h2>${data.projects.map(p=>`<div class="cv-item"><h3><a href="#research/${esc(p.id)}" aria-label="${esc(p.koreanTitle || '연구 프로젝트')}">${slot(p.koreanTitle)} ↗</a></h3><p>${slot(p.focus[0])}</p></div>`).join('')}</section><section class="cv-group"><h2>Technical skills</h2><div class="cv-skills"><span>PROGRAMMING</span><span>&nbsp;</span></div><div class="cv-skills"><span>CONTROL</span><span>&nbsp;</span></div><div class="cv-skills"><span>ROBOTICS</span><span>&nbsp;</span></div><div class="cv-skills"><span>ML & DATA</span><span>&nbsp;</span></div></section><section class="cv-group"><h2>Qualifications & activities</h2><div class="cv-item"><h3>&nbsp;</h3><p>&nbsp;</p></div><div class="cv-item"><h3>&nbsp;</h3><p>&nbsp;</p></div><div class="cv-item"><h3>&nbsp;</h3><p>&nbsp;</p></div></section></div></div></div>`;}
  function contact(){const github=safeUrl(data.profile.github);const email=/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(data.profile.email)?data.profile.email:'';return `<div style="margin-top:20px">${github?`<p><a href="${esc(github)}" target="_blank" rel="noopener noreferrer">GitHub ↗</a></p>`:''}${email?`<p><a href="mailto:${esc(email)}">${esc(email)}</a></p>`:''}</div>`;}
  function notFound(){return `<div class="wrap"><section class="page-intro"><h1>페이지를 찾을 수 없습니다.</h1><p>링크가 변경되었거나 아직 추가되지 않은 기록입니다.</p><div class="hero-links"><a class="button" href="#home">홈으로 이동 ↗</a></div></section></div>`;}
  function render(moveFocus=false) {
    const route=location.hash.slice(1)||'home';const [page,id]=route.split('/');
    document.title='Personal website';
    main.innerHTML=page==='home'?overview():page==='research'?research(id):page==='notes'?(id?article(id):archive()):page==='cv'?cv():notFound();
    document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===page);if(a.dataset.nav===page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
    if(page==='notes'&&!id){filterNotes();document.getElementById('note-search').addEventListener('input',e=>{query=e.target.value;filterNotes();});document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{selectedFilter=b.dataset.filter;filterNotes();}));}
    if(moveFocus){window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true});}
  }
  document.getElementById('year').textContent=new Date().getFullYear();
  for(const id of ['brand-name','footer-name','copyright-name']) document.getElementById(id).textContent=data.profile.name || '\u00a0';
  document.getElementById('brand-subtitle').textContent=data.profile.subtitle || '\u00a0';
  const github=safeUrl(data.profile.github);if(github){const link=document.getElementById('github-link');link.href=github;link.target='_blank';link.rel='noopener noreferrer';link.hidden=false;}
  window.addEventListener('hashchange',()=>render(true));render();
})();
